package in.orbitai.mobile;
import java.io.*;import java.util.*;import java.util.zip.*;import org.xmlpull.v1.*;import android.util.Xml;
/** Bounded, read-only XLSX extraction. Cached values only; no macros/formula execution. */
final class Workbook {
 static XmlPullParser parser(byte[] data)throws Exception{XmlPullParser p=Xml.newPullParser();p.setFeature(XmlPullParser.FEATURE_PROCESS_DOCDECL,false);p.setInput(new ByteArrayInputStream(data),"UTF-8");return p;}
 static String read(byte[] raw)throws Exception{Map<String,byte[]> sheets=new TreeMap<>();byte[] shared=null;long total=0;int entries=0;try(ZipInputStream zip=new ZipInputStream(new ByteArrayInputStream(raw))){ZipEntry entry;while((entry=zip.getNextEntry())!=null){if(++entries>5000)throw new IOException("Workbook has too many ZIP entries");ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;boolean keep=entry.getName().equals("xl/sharedStrings.xml")||entry.getName().matches("xl/worksheets/sheet[0-9]+\\.xml");while((n=zip.read(b))!=-1){total+=n;if(total>20000000)throw new IOException("Expanded workbook limit: 20 MB");if(keep)out.write(b,0,n);}if(entry.getName().equals("xl/sharedStrings.xml"))shared=out.toByteArray();else if(keep)sheets.put(entry.getName(),out.toByteArray());}}
  if(sheets.isEmpty())throw new IOException("No XLSX worksheets found");List<String> strings=new ArrayList<>();if(shared!=null){XmlPullParser p=parser(shared);StringBuilder item=null;for(int event=p.getEventType();event!=XmlPullParser.END_DOCUMENT;event=p.next()){if(event==XmlPullParser.START_TAG&&p.getName().equals("si"))item=new StringBuilder();if(event==XmlPullParser.START_TAG&&p.getName().equals("t")&&item!=null)item.append(p.nextText());if(event==XmlPullParser.END_TAG&&p.getName().equals("si")){strings.add(item.toString());if(strings.size()>100000)throw new IOException("Too many shared strings");}}}
  StringBuilder out=new StringBuilder("XLSX cached/raw values; formulas are not evaluated. Dates may be Excel serial numbers.\n");int cells=0;for(Map.Entry<String,byte[]> sheet:sheets.entrySet()){out.append("\nWorksheet ").append(sheet.getKey()).append("\n");XmlPullParser p=parser(sheet.getValue());String type="",value="";int column=0,lastColumn=0;boolean inCell=false;for(int event=p.getEventType();event!=XmlPullParser.END_DOCUMENT;event=p.next()){if(event==XmlPullParser.START_TAG){String name=p.getName();if(name.equals("row")){lastColumn=0;}if(name.equals("c")){inCell=true;type=p.getAttributeValue(null,"t");value="";String ref=p.getAttributeValue(null,"r");column=0;if(ref!=null)for(int k=0;k<ref.length()&&Character.isLetter(ref.charAt(k));k++)column=column*26+(Character.toUpperCase(ref.charAt(k))-'A'+1);if(column>256)throw new IOException("Workbook limit: 256 columns");if(++cells>20000)throw new IOException("Workbook limit: 20,000 cells");}else if(inCell&&(name.equals("v")||name.equals("t")))value+=p.nextText();}else if(event==XmlPullParser.END_TAG){if(p.getName().equals("c")){if("s".equals(type)){try{value=strings.get(Integer.parseInt(value));}catch(Exception e){throw new IOException("Invalid workbook shared-string reference");}}for(int k=lastColumn;k<Math.max(lastColumn,column-1);k++)out.append(',');if(lastColumn>0)out.append(',');out.append('"').append(value.replace("\"","\"\"")).append('"');lastColumn=Math.max(column,lastColumn+1);inCell=false;}if(p.getName().equals("row"))out.append('\n');}if(out.length()>300000)throw new IOException("Extracted workbook limit: 300,000 characters");}}
  return out.toString();
 }
}
